engine.docStyleTerms:
function docStyleTerms(paragraphs) {
  var QUOTED = /([“"])([^“”"\r\n]{1,60}?)([”"])/g;
  var MEANS = /^\s*(shall\s+mean|shall\s+have\s+the\s+meaning|ha(?:s|ve)\s+the\s+meaning|means?|includes?|refers\s+to)\b/i;
  var LEAD = /^\s*(?:[(\[]?[0-9A-Za-z]{1,6}(?:\.[0-9]{1,3})*[.)\]]?\s+)?$/;
