    var text = String((p && p.text) || ""), m;
    QUOTED.lastIndex = 0;
    while ((m = QUOTED.exec(text))) {
      var start = m.index, end = start + m[0].length;
      var curly = m[1] === "“" && m[3] === "”", straight = m[1] === '"' && m[3] === '"';
      var term = m[2].replace(/\s+/g, " ").trim();
