      var open = before.lastIndexOf("("), paren = open >= 0 && open > before.lastIndexOf(")");
      // a short aside before the verb still defines it ("“Sell” (and its derivatives) means …" — Feno's, missed: the owner, 10-23)
      var verb = MEANS.exec(after.replace(/^\s*\([^()]{1,60}\)/, ""));
      var lead = LEAD.test(text.slice(0, start)) && /^\s*[:–—-]/.test(after);
      if (!(curly || straight) || !/^[A-Z0-9]/.test(term) || term.split(" ").length > 8 || /^[\d\s.,]+$/.test(term) || !(paren || verb || lead)) {
        // A straight quote that closed nothing useful may open the next term.
        QUOTED.lastIndex = start + 1;
        continue;
      }
      if (seen[term]) continue;
      seen[term] = true;
      var snippet = m[0];
      if (paren) {
        var from = start - before.length + open, shut = text.indexOf(")", end);
        if (shut >= 0 && shut - from < 60) snippet = text.slice(from, shut + 1);
