      else snippet = m[0] + after.replace(/^\s+/, "").charAt(0);
      // how: [FMT-FIX] defined in a definitions list ("Records" means …) or inline in the text (the "Materials")
      out.push({ term: term, quote: curly ? "curly" : "straight", snippet: clip(snippet), i: i, how: paren ? "inline" : "definitions" });
    }
  });
