      /^(?:OutlineLevel)?([1-9])$/.exec(String(p.outlineLevel == null ? "" : p.outlineLevel));
    return m ? Number(m[1]) : 0;
  }

  // Headings: a heading style or outline level; else a short bold or
  // all-capitals line with a number, at its list level or number depth.
  // Tables and the table of contents are left out of headings, numbering
  // and body text.
  var heads = [], bodyParas = [], counted = 0, auto = 0, typed = 0, pats = {}, patOrder = [], cands = [];
  var refs = { Section: 0, Clause: 0, Article: 0, "§": 0 };
  var VERB = /\b(shall|will|may|must|is|are|agrees?|has|have)\b/i;
  // [MAIN-BODY] The agreement's own headings: up to its signature block or its first exhibit, as Format Check reads it —
  // what follows (a research plan, a policy) is set its own way, and its numbered list ("1. Rationale…") or a sentence in
