// docStyleParties(paragraphs, terms) — the parties the preamble names: each term it defines in a parenthesis before
// the recitals or the first clause (not the agreement's own names), with the name in front of it. [{ term, name, i }].

engine.docStyleParties:
function docStyleParties(paragraphs, terms) {
  var P = paragraphs || [], end = Math.min(P.length, 15);
  for (var k = 1; k < end; k++) {
    if (/^(WHEREAS|W\s?I\s?T\s?N\s?E\s?S\s?S|RECITALS?\b|BACKGROUND\b|NOW,? THEREFORE|ARTICLE\s+(?:1|I)\b|1\.?\s)/i.test(String((P[k] && P[k].text) || "").trim())) { end = k; break; }
