  return (terms || []).filter(function (x) { return x.i < end && /^\(/.test(String(x.snippet || "")) && !NOT.test(x.term); }).map(function (x) {
    var text = String((P[x.i] && P[x.i].text) || ""), at = text.indexOf(String(x.snippet).replace(/…$/, "")), m, name = "";
